#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s; 
    if(!(cin >> s)) return 0;
    int n = (int)s.size();
    vector<int> z(n);
    int l = 0, r = 0;
    for (int i = 1; i < n; ++i) {
        if (i <= r) z[i] = min(r - i + 1, z[i - l]);
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) ++z[i];
        if (i + z[i] - 1 > r) l = i, r = i + z[i] - 1;
    }
    long long ans = 0;
    for (int len = 1; 2 * len < n; ++len)
        if (z[len] >= len) ++ans;
    cout << ans << '\n';
    return 0;
}

СКРИПТ ДЛЯ ПРОХОДА АНКЕТИРОВАНИЯ  WSP

сейчас происходит анкетирование wsp и как вы знаете там нужно кликать на вопросы несколько десятков раз

вот простенький скрипт который просто ставит 9-10 баллов

(function() {
    // Находим все блоки с вопросами
    const questions = document.querySelectorAll('.v-questionnaire-question');

    questions.forEach(question => {
        // Внутри каждого вопроса ищем все label (подписи к кнопкам)
        const labels = question.querySelectorAll('label');
        const validOptions = [];

        // Собираем только те варианты, где текст равен "9" или "10"
        labels.forEach(label => {
            const text = label.innerText.trim();
            if (text === '9' || text === '10') {
                validOptions.push(label);
            }
        });

        // Если нашли нужные варианты (чтобы избежать ошибок на заголовках)
        if (validOptions.length > 0) {
            // Выбираем случайный индекс (0 или 1)
            const randomIndex = Math.floor(Math.random() * validOptions.length);

            // Эмулируем клик по выбранному варианту
            validOptions[randomIndex].click();
        }
    });

    console.log('Готово! Проставлены оценки 9 или 10.');
})();

